		if !got[i].Start.Equal(time.Unix(want, 0)) {
			t.Fatalf("window %d starts at %v, want %v", i, got[i].Start, want)
		}
	}
}

func TestMerge(t *testing.T) {
	a := New(time.Minute)
	b := New(time.Minute)
	a.Add(time.Unix(0, 0), 1)
	a.Add(time.Unix(0, 0), 3)
	b.Add(time.Unix(0, 0), 10)
