188				// Same instant on every goroutine: always accepted.
189				if err := a.Add(time.Unix(0, 0), 1); err != nil {
190					t.Errorf("Add: %v", err)
191				}
192				if err := a.Merge(b); !errors.Is(err, ErrWindowMismatch) {
193					t.Errorf("Merge: %v", err)
194				}
195			}()
196		}
197		wg.Wait()
198		var total int64
199		for _, w := range a.Windows() {
200			total += w.Count
201		}
202		if total != 4 {
203			t.Fatalf("failed merges altered receiver: total count %d", total)
204		}
205	}
