	}
	a.Merge(src) // a: buckets 0,100..199
	for i := 1; i < 50; i++ {
		a.Add(time.Unix(int64(i), 0), float64(i)) // backfill into a
	}
	b := New(time.Second)
	b.Add(time.Unix(50, 0), 500)
	b.Merge(src) // b: buckets 50,100..199
	for i := 51; i < 60; i++ {
		b.Add(time.Unix(int64(i), 0), float64(i)) // backfill into b
