package rollup

import (
	"math"
	"sync"
	"testing"
	"time"
)

// buildRoller files one sample per window at base+i*window for i in [0,n).
func buildRollerTB(t *testing.T, window time.Duration, n int) *Roller {
	t.Helper()
	r := New(window)
	base := time.Unix(0, 0)
	for i := 0; i < n; i++ {
		if err := r.Add(base.Add(time.Duration(i)*window), float64(i)); err != nil {
			t.Fatal(err)
		}
	}
	return r
}

func startsOf(ws []Window) []int64 {
	out := make([]int64, len(ws))
	for i, w := range ws {
		out[i] = w.Start.Unix()
	}
	return out
}

func eqStarts(t *testing.T, got []Window, want ...int64) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("got starts %v, want %v", startsOf(got), want)
	}
	for i, s := range want {
		if got[i].Start.Unix() != s {
			t.Fatalf("got starts %v, want %v", startsOf(got), want)
		}
	}
}

func TestScratchRangeBasic(t *testing.T) {
	r := buildRollerTB(t, 10*time.Second, 4) // windows at 0,10,20,30
	at := func(s int64) time.Time { return time.Unix(s, 0) }

	// Boundary attribution: [from, to) — window at from in, window at to out.
	eqStarts(t, r.Range(at(0), at(30)), 0, 10, 20)
	eqStarts(t, r.Range(at(10), at(20)), 10)
	eqStarts(t, r.Range(at(0), at(40)), 0, 10, 20, 30)
	// from inside a window: the window owning from leads the result.
	eqStarts(t, r.Range(at(5), at(25)), 0, 10, 20)
	eqStarts(t, r.Range(at(15), at(16)), 10)
	// to inside a window: the window owning instants before to is included.
	eqStarts(t, r.Range(at(0), at(1)), 0)
	// Empty cases: no error, empty collection.
	eqStarts(t, r.Range(at(5), at(5)))
	eqStarts(t, r.Range(at(10), at(10)))
