func TestScratchCursorConcurrent(t *testing.T) {
	r := buildRollerTB(t, time.Millisecond, 1000)
	src := buildRollerTB(t, time.Millisecond, 100)
	c := r.Cursor(time.Unix(0, 0), time.Unix(100, 0))
	stop := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(3)
	go func() { // appends
		defer wg.Done()
		for i := 1000; ; i++ {
			select {
			case <-stop:
				return
			default:
			}
			if err := r.Add(time.Unix(0, int64(i)*int64(time.Millisecond)), 1); err != nil {
				return
			}
		}
	}()
	go func() { // merges
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
			}
			r.Merge(src)
		}
	}()
	go func() { // range readers
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
			}
			got := r.Range(time.Unix(0, 0), time.Unix(2, 0))
			for i := 1; i < len(got); i++ {
				if !got[i-1].Start.Before(got[i].Start) {
					t.Errorf("range out of order")
					return
				}
			}
		}
	}()
	var total int
	prev := int64(-1)
	for {
		batch := c.Next(37)
		if len(batch) == 0 {
			break
		}
		for _, w := range batch {
			if w.Start.UnixMilli() <= prev {
				t.Fatalf("cursor repeated or reordered windows at %v", w.Start)
			}
			prev = w.Start.UnixMilli()
			total++
		}
	}
	close(stop)
	wg.Wait()
	if total != 1000 {
		t.Fatalf("cursor delivered %d windows, want 1000", total)
	}
}

