func TestScratchMergeWithBackfillBuffers(t *testing.T) {
	// Both sides carry unflushed backfill buffers; merge must unite all.
	a := New(time.Second)
	a.Add(time.Unix(0, 0), 1)
	src := New(time.Second)
	for i := 100; i < 200; i++ {
		src.Add(time.Unix(int64(i), 0), float64(i))
	}
	a.Merge(src) // a: buckets 0,100..199
	for i := 1; i < 50; i++ {
		a.Add(time.Unix(int64(i), 0), float64(i)) // backfill into a
	}
	b := New(time.Second)
	b.Add(time.Unix(50, 0), 500)
	b.Merge(src) // b: buckets 50,100..199
	for i := 51; i < 60; i++ {
		b.Add(time.Unix(int64(i), 0), float64(i)) // backfill into b
	}
	if err := a.Merge(b); err != nil {
		t.Fatal(err)
	}
	got := a.Windows()
	if len(got) != 200 {
		t.Fatalf("got %d windows, want 200", len(got))
	}
	for i, w := range got {
		if w.Start.Unix() != int64(i) {
			t.Fatalf("window %d starts at %v", i, w.Start)
		}
	}
	w, _ := a.Window(time.Unix(100, 0))
	if w.Count != 2 || w.Sum != 200 { // window 100 came from src into both a and b
		t.Fatalf("merged window 100: %+v", w)
	}
	w, _ = a.Window(time.Unix(50, 0))
	if w.Sum != 500 {
		t.Fatalf("window 50: %+v", w)
	}
	// Source unchanged.
	if got := len(b.Windows()); got != 110 {
		t.Fatalf("source changed: %d windows", got)
	}
	// Self-merge with a live backfill buffer.
	c := New(time.Second)
	c.Add(time.Unix(0, 0), 1)
	c.Merge(src)
	for i := 1; i < 10; i++ {
		c.Add(time.Unix(int64(i), 0), 1)
	}
	if err := c.Merge(c); err != nil {
		t.Fatal(err)
	}
	w, _ = c.Window(time.Unix(5, 0))
	if w.Count != 2 || w.Sum != 2 {
		t.Fatalf("self-merge backfill window: %+v", w)
	}
}

