// buildRoller files one sample per window at base+i*window for i in [0,n).
func buildRollerTB(t *testing.T, window time.Duration, n int) *Roller {
	t.Helper()
	r := New(window)
	base := time.Unix(0, 0)
	for i := 0; i < n; i++ {
		if err := r.Add(base.Add(time.Duration(i)*window), float64(i)); err != nil {
			t.Fatal(err)
		}
	}
	return r
}

func startsOf(ws []Window) []int64 {
	out := make([]int64, len(ws))
	for i, w := range ws {
		out[i] = w.Start.Unix()
	}
	return out
}

func eqStarts(t *testing.T, got []Window, want ...int64) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("got starts %v, want %v", startsOf(got), want)
	}
	for i, s := range want {
		if got[i].Start.Unix() != s {
			t.Fatalf("got starts %v, want %v", startsOf(got), want)
		}
	}
}

